"""Exact verification of the logistic-Chebyshev bridge identity.

Confirms f^n(x) = (1 - T_{2^n}(1 - 2x))/2 with exact rational arithmetic, so the
polynomial identity is checked with zero error even for x outside [0,1].
"""
from __future__ import annotations
from fractions import Fraction
from typing import Union

Number = Union[float, Fraction]


def logistic(x: Number) -> Number:
    return 4 * x * (1 - x)


def iterate(n: int, x: Number) -> Number:
    for _ in range(n):
        x = logistic(x)
    return x


def chebyshev_T(m: int, t: Number) -> Number:
    one = t * 0 + 1
    if m == 0:
        return one
    if m == 1:
        return t
    a, b = one, t
    for _ in range(2, m + 1):
        a, b = b, 2 * t * b - a
    return b


def closed_form(n: int, x: Number) -> Number:
    return (1 - chebyshev_T(2 ** n, 1 - 2 * x)) / 2


if __name__ == "__main__":
    xs = [Fraction(1, 10), Fraction(1, 2), Fraction(13, 10), Fraction(-2, 5)]
    ok = all(iterate(n, x) == closed_form(n, x) for n in range(5) for x in xs)
    print("bridge identity exact for all tested (n, x):", ok)

"""Chaos as angle doubling: f^n(sin^2 phi) = sin^2(2^n phi).

Tracks a logistic orbit both directly and through the angle coordinate
x = sin^2(phi), where the dynamics is simply phi -> 2 phi.
"""
from __future__ import annotations
import math


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def orbit_direct(x0: float, steps: int) -> list[float]:
    xs = [x0]
    for _ in range(steps):
        xs.append(logistic(xs[-1]))
    return xs


def orbit_angle(x0: float, steps: int) -> list[float]:
    phi = math.asin(math.sqrt(x0))
    return [math.sin(2 ** n * phi) ** 2 for n in range(steps + 1)]


if __name__ == "__main__":
    x0 = 0.3
    d = orbit_direct(x0, 8)
    a = orbit_angle(x0, 8)
    for n, (di, ai) in enumerate(zip(d, a)):
        print(f"n={n}: direct={di:.9f}  angle={ai:.9f}  diff={abs(di-ai):.2e}")

"""Periodic points of the logistic map and the 2^n law (n = 1, 2).

Enumerates the fixed points of f and f^2 and verifies the exact factorisation
f^2(x) - x = -4 x (x - 3/4)(16 x^2 - 20 x + 5).
"""
from __future__ import annotations
import math


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def f2(x: float) -> float:
    return logistic(logistic(x))


def fixed_points_n1() -> list[float]:
    return [0.0, 0.75]  # roots of x(3 - 4x) = 0


def fixed_points_n2() -> list[float]:
    r = math.sqrt(5.0)
    return [0.0, 0.75, (5.0 - r) / 8.0, (5.0 + r) / 8.0]


if __name__ == "__main__":
    print("n=1 fixed points (count = 2 = 2^1):")
    for x in fixed_points_n1():
        print(f"   x={x:.6f}  f(x)={logistic(x):.6f}")
    print("n=2 fixed points (count = 4 = 2^2):")
    for x in fixed_points_n2():
        print(f"   x={x:.6f}  f^2(x)={f2(x):.6f}")
    err = max(abs((f2(x) - x) -
                  (-4 * x * (x - 0.75) * (16 * x * x - 20 * x + 5)))
              for x in [-0.3, 0.15, 0.42, 0.88, 1.1])
    print(f"factorisation max error: {err:.2e}")

