function ANGLE_ORBIT(x0, steps):
    phi0 <- arcsin(sqrt(x0))
    orbit <- empty list
    for n from 0 to steps:
        append sin(2^n * phi0)^2 to orbit
    return orbit

function PERIODIC_POINTS(n):
    m <- 2^n
    solutions <- empty set
    # cos(2m phi) = cos(2 phi)  <=>  2m phi = +/- 2 phi + 2 pi k
    for k from 0 to m:
        phi_a <- k*pi/(m + 1)      # from 2m phi = -2 phi + 2 pi k
        phi_b <- k*pi/(m - 1)      # from 2m phi =  2 phi + 2 pi k  (m > 1)
        for phi in {phi_a, phi_b} with 0 <= phi <= pi/2:
            add sin(phi)^2 to solutions
    return sorted(solutions)   # exactly 2^n points

