from __future__ import annotations
import math


def periodic_points(n: int, tol: float = 1e-9) -> list[float]:
    """Points x in [0,1] with f^n(x) = x, via cos(2^{n+1} phi) = cos(2 phi)."""
    m: int = 2 ** n
    sols: list[float] = []
    for k in range(m + 1):
        cands = [k * math.pi / (m + 1)]
        if m > 1:
            cands.append(k * math.pi / (m - 1))
        for phi in cands:
            if -tol <= phi <= math.pi / 2 + tol:
                x = math.sin(phi) ** 2
                if all(abs(x - s) > tol for s in sols):
                    sols.append(x)
    return sorted(sols)
